<script lang="ts">
  import { onMount } from 'svelte';
  import { AutomationApiError, emptyAutomation, loadAutomation, saveAutomation, validateAutomation, type AutomationDocument, type AutomationEnvelope, type AutomationFieldError, type AutomationSchedule } from './lib/automation';
  import { DashboardClient, fetchScheduleOccurrences, simulateScenario, SimulationApiError } from './lib/api';
  import { displayedCountdownMs, displayedScheduleCountdownMs, formatAge, formatCountdown, formatDateTimeValue, formatDuration, formatStateEntry, formatUtcDateTime, formatUtcOffset, formatValue, initialDashboardState, reduceDashboardState, triggerLabel, triggerSummary, type DashboardState, type DisplayBlock, type DisplayBlockSchedule, type DisplayEndpoint, type DisplayExecution, type DisplayExecutionOrigin, type DisplayExecutionTrigger, type DisplayScheduleOccurrence, type DisplaySimulation, type DisplayStateValue } from './lib/state';
  import { applySimulationResult, createSimulationDraft, forceTriggerInput, reconcileScheduleSelection, schedulePreviewDefault, toSimulationScenario, validateSimulationDraft, type SimulationDraft, type SimulationValue } from './lib/simulation';
  import ScheduleEditor from './lib/ScheduleEditor.svelte';
  import SignalsSection from './lib/SignalsSection.svelte';
  import ExecutionSignalDetail from './lib/ExecutionSignalDetail.svelte';
  import SimulationResultContext from './lib/SimulationResultContext.svelte';
  import ExternalInputsSection from './lib/ExternalInputsSection.svelte';

  let state: DashboardState = initialDashboardState;
  let automation: AutomationEnvelope | null = null;
  let draft: AutomationDocument = emptyAutomation();
  let automationLoading = true;
  let automationSaving = false;
  let automationError: string | null = null;
  let serverErrors: AutomationFieldError[] = [];
  let conflictLatest: AutomationEnvelope | null = null;
  let saveNotice: string | null = null;
  let simulationDraft: SimulationDraft | null = null;
  let simulationResult: DisplaySimulation | null = null;
  let simulationRunning = false;
  let simulationError: string | null = null;
  let simulationFieldErrors: string[] = [];
  let simulationPreviewLoading = false;
  let simulationPreviewError: string | null = null;
  let selectedScheduleName: string | null = null;
  let scheduleDetailPreviews: DisplayScheduleOccurrence[] = [];
  let scheduleDetailLoading = false;
  let scheduleDetailError: string | null = null;

  $: snapshot = state.snapshot;
  $: blocks = snapshot?.blocks ?? [];
  $: selectedBlock = blocks.find((block) => block.id === state.selectedBlockId) ?? blocks[0] ?? null;
  $: selectedBlockId = selectedBlock?.id ?? null;
  $: draftBlock = (draft.blocks ?? []).find((block) => block.id === selectedBlockId) ?? null;
  $: selectedExecution = selectedBlock?.executions.find((execution) => execution.executionId === state.selectedExecutionId) ?? null;
  $: pendingRestart = Boolean(snapshot?.restartRequired || automation?.restartRequired || (snapshot?.activeStructuralRevision !== null && snapshot?.savedStructuralRevision !== null && String(snapshot?.activeStructuralRevision) !== String(snapshot?.savedStructuralRevision)));
  $: source = draftBlock?.source ?? selectedBlock?.source ?? '';
  $: simulationErrors = simulationDraft ? validateSimulationDraft(simulationDraft) : [];
  // Simulation and preview use the persisted per-block revision. The logic
  // revision remains available for old M8 responses, but is not the schedule
  // definition's concurrency token.
  $: simulationRevision = selectedBlock?.activeRevision ?? selectedBlock?.activeLogicRevision ?? null;
  $: canSimulate = Boolean(simulationDraft && simulationRevision !== null && simulationErrors.length === 0 && !simulationRunning && (simulationDraft.triggerType !== 'schedule' || snapshot?.activeStructuralRevision !== null));
  $: simulationTriggerInput = simulationDraft?.triggerType === 'input' ? simulationDraft.inputs.find((input) => input.endpoint === simulationDraft?.triggerEndpoint) ?? null : null;
  $: selectedSchedule = selectedBlock?.schedules.find((schedule) => schedule.name === selectedScheduleName) ?? null;

  const dispatch = (action: Parameters<typeof reduceDashboardState>[1]) => { state = reduceDashboardState(state, action); };
  const documentBlock = (id: string): NonNullable<AutomationDocument['blocks']>[number] | null => (draft.blocks ?? []).find((block) => block.id === id) ?? null;

  async function refreshAutomation(): Promise<void> {
    automationLoading = true; automationError = null;
    try { const loaded = await loadAutomation(); automation = loaded; draft = loaded.document; conflictLatest = null; serverErrors = []; saveNotice = null; } catch (error) { automationError = error instanceof Error ? error.message : String(error); } finally { automationLoading = false; }
  }
  function updateSource(value: string): void { if (!selectedBlockId) return; draft = { ...draft, blocks: (draft.blocks ?? []).map((block) => block.id === selectedBlockId ? { ...block, source: value } : block) }; serverErrors = []; saveNotice = null; }
  function scheduleTemplate(name: string, kind: AutomationSchedule['kind'] = 'fixed'): AutomationSchedule {
    if (kind === 'interval') return { name, enabled: true, kind, every: '1h' };
    if (kind === 'astronomical') return { name, enabled: true, kind, anchor: 'sunset', offset: '0s' };
    return { name, enabled: true, kind, at: '12:00' };
  }
  function updateSchedule(index: number, patch: Partial<AutomationSchedule>): void {
    if (!selectedBlockId || !draftBlock) return;
    draft = { ...draft, blocks: (draft.blocks ?? []).map((block) => block.id === selectedBlockId ? { ...block, schedules: block.schedules.map((schedule, current) => current === index ? { ...schedule, ...patch } : schedule) } : block) };
    serverErrors = []; saveNotice = null;
  }
  function updateScheduleKind(index: number, kind: AutomationSchedule['kind']): void {
    if (!draftBlock) return;
    const current = draftBlock.schedules[index]; if (!current) return;
    updateSchedule(index, scheduleTemplate(current.name, kind));
  }
  function updateScheduleWeekdays(index: number, value: string): void {
    const weekdays = value.split(',').map((item) => item.trim().toLowerCase()).filter(Boolean) as AutomationSchedule['weekdays'];
    updateSchedule(index, { weekdays: weekdays?.length ? weekdays : undefined });
  }
  function addSchedule(): void {
    if (!selectedBlockId || !draftBlock || draftBlock.schedules.length >= 32) return;
    const names = new Set(draftBlock.schedules.map((schedule) => schedule.name)); let suffix = 1; let name = `schedule_${suffix}`;
    while (names.has(name)) { suffix += 1; name = `schedule_${suffix}`; }
    draft = { ...draft, blocks: (draft.blocks ?? []).map((block) => block.id === selectedBlockId ? { ...block, schedules: [...block.schedules, scheduleTemplate(name)] } : block) };
    selectedScheduleName = name; serverErrors = []; saveNotice = null;
  }
  function removeSchedule(index: number): void {
    if (!selectedBlockId || !draftBlock) return;
    const removed = draftBlock.schedules[index];
    draft = { ...draft, blocks: (draft.blocks ?? []).map((block) => block.id === selectedBlockId ? { ...block, schedules: block.schedules.filter((_, current) => current !== index) } : block) };
    if (removed?.name === selectedScheduleName) { selectedScheduleName = null; scheduleDetailPreviews = []; scheduleDetailError = null; }
    serverErrors = []; saveNotice = null;
  }
  function updateSchedules(schedules: AutomationSchedule[]): void {
    if (!selectedBlockId) return;
    draft = { ...draft, blocks: (draft.blocks ?? []).map((block) => block.id === selectedBlockId ? { ...block, schedules } : block) };
    serverErrors = []; saveNotice = null;
  }
  function blockDraftEnabled(id: string): boolean { return documentBlock(id)?.enabled ?? true; }
  function hasRecentOutput(block: DisplayBlock): boolean { return block.executions.some((execution) => execution.effects.length > 0); }
  function toggleEnabled(): void {
    if (!selectedBlock || !selectedBlockId) return;
    const next = !blockDraftEnabled(selectedBlockId);
    if (!next && (selectedBlock.pendingTimers.length || hasRecentOutput(selectedBlock))) {
      const details = selectedBlock.pendingTimers.length ? `${selectedBlock.pendingTimers.length} pending timer(s) will be cancelled` : 'recent outputs are present';
      if (!window.confirm(`Disable ${selectedBlockId}? ${details}. Disabling cancels timers but sends no output cleanup value.`)) return;
    }
    draft = { ...draft, blocks: (draft.blocks ?? []).map((block) => block.id === selectedBlockId ? { ...block, enabled: next } : block) }; saveNotice = null;
  }
  async function saveDraft(): Promise<void> {
    if (!automation || validateAutomation(draft).length || automationSaving) return;
    automationSaving = true; automationError = null; serverErrors = []; conflictLatest = null; saveNotice = null;
    try {
      const result = await saveAutomation(draft, automation.revision); const savedBlocks = result.blocks ?? []; const savedDocument = { ...draft, blocks: (draft.blocks ?? []).map((block) => { const saved = savedBlocks.find((item) => item.id === block.id); return saved ? { ...block, revision: saved.savedRevision } : block; }) }; automation = { ...automation, document: savedDocument, revision: result.revision, activeLogicRevision: result.activeLogicRevision, restartRequired: result.restartRequired }; draft = savedDocument; const cancelled = result.cancelledTimers?.length ? ` Cancelled timers: ${result.cancelledTimers.join(', ')}.` : ''; saveNotice = result.restartRequired ? 'Saved. Structural changes require a desktop restart before activation.' : result.logicActivated ? `Saved and activated for the selected block(s).${cancelled}` : 'Saved. The active runtime will use the source at its next activation.';
    } catch (error) { if (error instanceof AutomationApiError) { serverErrors = error.fieldErrors; conflictLatest = error.latest; automationError = error.message; } else automationError = error instanceof Error ? error.message : String(error); } finally { automationSaving = false; }
  }
  function reloadConflict(): void { if (!conflictLatest) return; automation = conflictLatest; draft = conflictLatest.document; conflictLatest = null; automationError = null; serverErrors = []; saveNotice = null; }
  function blockScopedSnapshot(next: DisplayBlock | null): Parameters<typeof createSimulationDraft>[0] | null {
    if (!snapshot || !next) return null;
    return { ...snapshot, blocks: [next], pendingTimers: next.pendingTimers, executions: next.executions, state: next.state, automation: { inputs: next.inputs, outputs: next.outputs, bindings: next.bindings, signalBindings: next.signalBindings, source: next.source } };
  }
  function resetSimulationAux(): void { simulationResult = null; simulationError = null; simulationFieldErrors = []; simulationPreviewError = null; selectedScheduleName = null; scheduleDetailPreviews = []; scheduleDetailError = null; }
  function selectBlock(id: string): void { if (!snapshot?.blocks.some((block) => block.id === id)) return; dispatch({ type: 'select_block', blockId: id }); const next = snapshot.blocks.find((block) => block.id === id); simulationDraft = next ? createSimulationDraft(blockScopedSnapshot(next) ?? snapshot, null) : null; resetSimulationAux(); }
  function selectExecution(executionId: number): void { dispatch({ type: 'select_execution', executionId }); }
  function useForSimulation(execution: DisplayExecution | null = selectedExecution): void { if (!snapshot || !selectedBlock) return; simulationDraft = createSimulationDraft(blockScopedSnapshot(selectedBlock) ?? snapshot, execution); resetSimulationAux(); }
  function observeSnapshot(next: NonNullable<DashboardState['snapshot']>): void {
    const draft = simulationDraft;
    if (!draft || draft.blockId !== state.selectedBlockId) { useForSimulation(null); return; }
    const nextBlock = next.blocks.find((block) => block.id === draft.blockId);
    if (nextBlock) simulationDraft = reconcileScheduleSelection(draft, nextBlock.schedules);
  }

  onMount(() => {
    void refreshAutomation();
    const client = new DashboardClient({ handlers: {
      onSnapshot: (next) => { observeSnapshot(next); dispatch({ type: 'snapshot_loaded', snapshot: next, nowMs: Date.now() }); const first = next.blocks.find((block) => block.id === state.selectedBlockId) ?? next.blocks[0]; if (!simulationDraft && first) simulationDraft = createSimulationDraft(blockScopedSnapshot(first) ?? next, null); },
      onEvent: (event) => { if (event.kind === 'update') observeSnapshot(event.snapshot); dispatch({ type: 'event_received', event }); }, onStreamOpen: () => dispatch({ type: 'stream_open' }), onStreamLost: (error) => dispatch({ type: 'stream_lost', error }), onError: (error) => dispatch({ type: 'stream_error', error: error.message })
    } }); void client.start(); const ticker = window.setInterval(() => dispatch({ type: 'tick', nowMs: Date.now() }), 250); return () => { window.clearInterval(ticker); client.stop(); };
  });
  function displayTime(value: string): string { const date = new Date(value); return Number.isNaN(date.valueOf()) ? value : date.toLocaleTimeString(); }
  function displayFields(fields: Record<string, string | number | boolean | null>): string { return Object.entries(fields).map(([key, value]) => `${key}=${String(value)}`).join(' '); }
  function originSummary(origin: DisplayExecutionOrigin | null): string {
    if (!origin) return '—';
    if (origin.kind === 'http') return `HTTP poll ${origin.poll} / ${origin.value}`;
    if (origin.kind === 'webhook') return `Webhook ${origin.source}`;
    if (origin.kind === 'signal') return `Signal ${origin.signal}`;
    return origin.groupAddress ? `KNX ${origin.groupAddress}` : 'KNX';
  }
  function simulationMin(dpt: string | undefined): number { return dpt === '9.001' ? -670760 : 0; }
  function simulationMax(dpt: string | undefined): number { return dpt === '9.001' ? 670760 : 100; }
  function simulationStep(dpt: string | undefined): string { return dpt === '9.001' ? '0.01' : '1'; }
  function valueForEndpoint(endpoint: DisplayEndpoint): string { return formatValue(endpoint.observed ?? null); }
  function blockCountdown(timerName: string): number | null { if (!snapshot || !selectedBlock) return null; const timer = selectedBlock.pendingTimers.find((item) => item.name === timerName); if (!timer) return null; if (state.stale) return Math.max(0, timer.dueAtMs - ((state.staleAtMs ?? state.nowMs) - snapshot.capturedAtMs - (snapshot.clockOffsetMs ?? 0))); return Math.max(0, timer.dueAtMs - (state.nowMs - snapshot.capturedAtMs - (snapshot.clockOffsetMs ?? 0))); }
  function scheduleCountdown(scheduleName: string): string { if (!snapshot || !selectedBlock) return '—'; if (state.stale) return 'stale'; return formatCountdown(displayedScheduleCountdownMs(state, selectedBlock.id, scheduleName)); }
  function scheduleStatusPill(status: DisplayBlockSchedule['status']): string { return status === 'active' ? 'good' : status === 'paused' ? 'muted' : 'bad'; }
  function scheduleOutcome(schedule: DisplayBlockSchedule): string { return schedule.lastOutcome.status === 'none' ? '—' : `${schedule.lastOutcome.status}${schedule.lastOutcome.timeMs === null ? '' : ` @ ${schedule.lastOutcome.timeMs} ms`}`; }
  function scheduleReason(schedule: DisplayBlockSchedule): string | null { if (schedule.status === 'unavailable' || schedule.status === 'clock_error') return schedule.reason ?? (schedule.status === 'clock_error' ? 'The wall clock is invalid.' : 'No occurrence exists in the search window.'); return null; }
  function occurrenceNotes(occurrences: DisplayScheduleOccurrence[]): string[] {
    const notes: string[] = [];
    for (let i = 1; i < occurrences.length; i += 1) {
      const previous = occurrences[i - 1].utcOffsetSeconds; const current = occurrences[i].utcOffsetSeconds;
      if (previous !== null && current !== null && previous !== current) { notes.push('DST transition between these occurrences'); break; }
    }
    return notes;
  }
  async function selectSchedule(name: string): Promise<void> {
    selectedScheduleName = selectedScheduleName === name ? null : name;
    scheduleDetailPreviews = []; scheduleDetailError = null;
    if (selectedScheduleName === null || !selectedBlockId) return;
    scheduleDetailLoading = true;
    try { const preview = await fetchScheduleOccurrences(selectedBlockId, selectedScheduleName, { count: 3 }); if (selectedScheduleName === preview.schedule && state.selectedBlockId === selectedBlockId) scheduleDetailPreviews = preview.occurrences; } catch (error) { scheduleDetailError = error instanceof Error ? error.message : String(error); } finally { scheduleDetailLoading = false; }
  }
  function stateValue(value: DisplayStateValue | undefined): string { return formatStateEntry(value); }
  function updateSimulationDraft(next: Partial<SimulationDraft>): void { if (!simulationDraft) return; simulationDraft = forceTriggerInput({ ...simulationDraft!, ...next }); simulationResult = null; simulationError = null; simulationFieldErrors = []; }
  function simulationDraftRequired(): SimulationDraft { if (!simulationDraft) throw new Error('Simulation draft is unavailable'); return simulationDraft; }
  function inputValue(event: Event): string { return (event.currentTarget as HTMLInputElement).value; }
  function selectValue(event: Event): string { return (event.currentTarget as HTMLSelectElement).value; }
  function simulationBoolean(event: Event): SimulationValue { const value = selectValue(event); return value === '' ? null : value === 'true'; }
  function simulationNumber(event: Event): SimulationValue { const value = inputValue(event).trim(); if (!value) return null; const parsed = Number(value); return Number.isFinite(parsed) ? parsed : null; }
  function simulationAge(event: Event): number | null { const value = simulationNumber(event); return typeof value === 'number' ? value : null; }
  function simulationTriggerEndpoint(endpoint: string): void { if (!simulationDraft) return; const selected = simulationDraft.inputs.find((input) => input.endpoint === endpoint); updateSimulationDraft({ ...simulationDraft!, triggerType: 'input', triggerEndpoint: endpoint, triggerValue: selected?.value ?? null, previousValue: null }); }
  function simulationTriggerType(type: 'input' | 'timer' | 'schedule'): void { if (!simulationDraft) return; updateSimulationDraft({ ...simulationDraft!, triggerType: type }); if (type === 'schedule' && !simulationDraft.schedulePreviews.length && simulationDraft.triggerScheduleName) void loadSimulationPreviews(); }
  function simulationTimer(name: string): void { if (!simulationDraft) return; const timer = simulationDraft.pendingTimers.find((item) => item.name === name); updateSimulationDraft({ ...simulationDraft!, triggerType: 'timer', triggerTimerName: name, timerFiredAtMs: timer?.dueAtMs ?? simulationDraft.timerFiredAtMs }); }
  function simulationFiredAt(value: string): void { const parsed = Number(value); updateSimulationDraft({ timerFiredAtMs: Number.isInteger(parsed) && parsed >= 0 ? parsed : null }); }
  function simulationSchedule(name: string): void { if (!simulationDraft) return; const schedule = (selectedBlock?.schedules ?? []).find((item) => item.name === name); updateSimulationDraft({ ...simulationDraft!, triggerType: 'schedule', triggerScheduleName: name, scheduleOccurrenceAtMs: schedule?.nextOccurrenceUtcMs ?? null, schedulePreviews: [] }); if (name) void loadSimulationPreviews(); }
  function simulationOccurrence(utcMs: number): void { if (!simulationDraft) return; updateSimulationDraft({ ...simulationDraft!, scheduleOccurrenceAtMs: Number.isInteger(utcMs) && utcMs >= 0 ? utcMs : null }); }
  async function loadSimulationPreviews(): Promise<void> {
    if (!simulationDraft || !simulationDraft.triggerScheduleName || !simulationDraft.blockId) return;
    simulationPreviewLoading = true; simulationPreviewError = null;
    const blockId = simulationDraft.blockId; const schedule = simulationDraft.triggerScheduleName;
    try { const preview = await fetchScheduleOccurrences(blockId, schedule, { count: 3 }); if (simulationDraft && simulationDraft.blockId === blockId && simulationDraft.triggerScheduleName === schedule) simulationDraft = { ...simulationDraft, schedulePreviews: preview.occurrences, scheduleOccurrenceAtMs: schedulePreviewDefault(preview.occurrences, simulationDraft.scheduleOccurrenceAtMs) }; } catch (error) { simulationPreviewError = error instanceof Error ? error.message : String(error); } finally { simulationPreviewLoading = false; }
  }
  async function runSimulation(): Promise<void> { if (!simulationDraft || simulationRevision === null || simulationErrors.length || simulationRunning) return; const prepared = forceTriggerInput(simulationDraft); const scenario = toSimulationScenario(prepared, simulationRevision, snapshot?.activeStructuralRevision ?? null); if (!scenario) return; simulationRunning = true; simulationError = null; simulationFieldErrors = []; try { simulationResult = await simulateScenario(scenario); simulationDraft = applySimulationResult(prepared, simulationResult); } catch (error) { if (error instanceof SimulationApiError) { simulationError = error.message; simulationFieldErrors = error.fieldErrors.map((item) => `${item.path}: ${item.message}`); } else simulationError = error instanceof Error ? error.message : String(error); } finally { simulationRunning = false; } }
</script>

<main>
  <header class="page-header"><div><p class="eyebrow">LogikSmith / Milestone 9</p><h1>Automation dashboard</h1></div><div class="status-cluster"><span class="status-pill {snapshot?.connection.state === 'connected' ? 'good' : 'muted'}">KNX {snapshot?.connection.state ?? 'starting'}</span>{#if state.stale}<span class="stale">Stream stale — countdowns frozen</span>{:else}<span class="status-pill good">Stream {state.streamStatus}</span>{/if}</div></header>
  {#if state.error}<div class="alert" role="alert">{state.error}</div>{/if}
  {#if snapshot}
    <section class="panel block-workspace" aria-label="Logic blocks">
      <div class="section-heading"><div><h2>Logic blocks</h2><p class="subtle">Configuration order · {blocks.length}/64 blocks</p></div><span class="revision-badge">Snapshot {state.revision}</span></div>
      {#if !blocks.length}<p class="empty">No blocks configured.</p>{:else}<div class="block-list" role="list">{#each blocks as block}<button type="button" class:selected={block.id === selectedBlockId} class:failed={block.lastResult.status === 'failed'} class="block-row" on:click={() => selectBlock(block.id)} aria-pressed={block.id === selectedBlockId}><span class="block-row-main"><strong>{block.id}</strong><span class="status-pill {block.activeEnabled ? 'good' : 'muted'}">{block.activeEnabled ? 'enabled' : 'disabled'}</span></span><span class="block-row-facts"><span>{block.lastResult.status === 'none' ? 'never run' : block.lastResult.status}</span><span>{block.lastResult.timeMs === null ? '—' : `${block.lastResult.timeMs} ms`}</span><span>{block.pendingTimers.length} timer{block.pendingTimers.length === 1 ? '' : 's'}</span><span>{block.schedules.length} schedule{block.schedules.length === 1 ? '' : 's'}</span>{#if block.activeLogicRevision !== block.savedLogicRevision}<span class="status-pill bad">revision mismatch</span>{/if}{#if pendingRestart}<span class="status-pill bad">restart required</span>{/if}</span></button>{/each}</div>{/if}
    </section>
    <SignalsSection signals={snapshot.signals} />
    <ExternalInputsSection externalInputs={snapshot.externalInputs} />
    {#if selectedExecution}
      <section class="panel execution-origin-panel" aria-label="Selected execution origin"><div class="section-heading"><h2>Execution origin</h2><span class="trigger-kind">{originSummary(selectedExecution.origin)}</span></div><p class="subtle">Transport provenance is supplied by the host and does not alter the Lua input event.</p></section>
    {/if}

    {#if selectedBlock}
      <ScheduleEditor schedules={draftBlock?.schedules ?? []} onChange={updateSchedules} />
      <ExecutionSignalDetail execution={selectedExecution} />
      <SimulationResultContext result={simulationResult} />
      <section class="panel editor" aria-label="Selected block"><div class="section-heading"><div><p class="eyebrow">Selected block</p><h2>{selectedBlock.id}</h2></div><button type="button" class="small-button" on:click={toggleEnabled}>{blockDraftEnabled(selectedBlock.id) ? 'Disable block' : 'Enable block'}</button></div>
        <p class="subtle">Active {selectedBlock.activeEnabled ? 'enabled' : 'disabled'} · saved {selectedBlock.savedEnabled ? 'enabled' : 'disabled'} · active persisted revision {selectedBlock.activeRevision ?? selectedBlock.activeLogicRevision ?? '—'} · saved {selectedBlock.savedRevision ?? selectedBlock.savedLogicRevision ?? '—'}</p>
        {#if selectedBlock.lastError}<div class="logic-error" role="alert"><strong>Last error: {selectedBlock.lastError.category}</strong>{#if selectedBlock.lastError.line !== null} line {selectedBlock.lastError.line}:{/if} {selectedBlock.lastError.message}</div>{/if}
        {#if saveNotice}<div class="success-notice" role="status">{saveNotice}</div>{/if}{#if automationError}<div class="alert" role="alert">{automationError}{#if conflictLatest}<button type="button" class="small-button" on:click={reloadConflict}>Reload latest</button>{/if}</div>{/if}
        <div class="source-editor"><div class="section-heading"><h3>Source</h3><span class="source-size">{new TextEncoder().encode(source).byteLength} / 65,536 bytes</span></div><textarea aria-label={`Lua source for ${selectedBlock.id}`} value={source} on:input={(event) => updateSource(inputValue(event))}></textarea><p class="source-reference">Handler contract: <code>handle(event, input, meta, state, ctx)</code>. <code>ctx</code> carries the captured time context (<code>ctx.now</code>, <code>ctx.sun.dawn/sunrise/sunset/dusk</code>, <code>ctx.sun.elevation/azimuth</code>). Schedule events expose <code>event.type == "schedule"</code> and <code>event.schedule</code>; input and timer fields are absent. Schedule rule edits are structural and require a desktop restart.</p></div>
        <div class="detail-columns"><div><h3>Endpoints and bindings</h3><div class="table-wrap"><table><thead><tr><th>Endpoint</th><th>Direction</th><th>DPT</th><th>Binding</th><th>Current</th></tr></thead><tbody>{#each [...selectedBlock.inputs, ...selectedBlock.outputs] as endpoint}<tr><td><code>{endpoint.name}</code></td><td>{endpoint.direction}</td><td>{endpoint.dpt}</td><td>{#if endpoint.bindingKind === 'signal'}<span class="status-pill good">signal</span> <code>{endpoint.signal ?? '—'}</code>{:else if endpoint.bindingKind === 'knx'}<span class="status-pill muted">KNX</span> <code>{endpoint.address || '—'}</code>{:else if endpoint.bindingKind === 'http'}<span class="status-pill good">HTTP</span> <code>{endpoint.source ?? '—'}</code>{:else if endpoint.bindingKind === 'webhook'}<span class="status-pill good">webhook</span> <code>{endpoint.source ?? '—'}</code>{:else}<span class="status-pill muted">unbound</span>{/if}</td><td><span class="value">{valueForEndpoint(endpoint)}</span>{#if endpoint.direction === 'output'} <span class="value requested">requested {formatValue(endpoint.requested ?? null)}</span>{/if}</td></tr>{/each}</tbody></table></div></div><div><h3>Revisions</h3><dl class="facts"><dt>Active persisted revision</dt><dd>{selectedBlock.activeRevision ?? selectedBlock.activeLogicRevision ?? '—'}</dd><dt>Saved persisted revision</dt><dd>{selectedBlock.savedRevision ?? selectedBlock.savedLogicRevision ?? '—'}</dd><dt>Active enabled</dt><dd>{String(selectedBlock.activeEnabled)}</dd><dt>Saved enabled</dt><dd>{String(selectedBlock.savedEnabled)}</dd><dt>Structure</dt><dd>{pendingRestart ? 'restart required' : 'active'}</dd></dl></div></div>
        <div class="detail-columns"><div><h3>Transient state</h3>{#if Object.keys(selectedBlock.state).length}<div class="table-wrap"><table><thead><tr><th>Key</th><th>Value</th></tr></thead><tbody>{#each Object.entries(selectedBlock.state) as [key, value]}<tr><td><code>{key}</code></td><td>{stateValue(value)}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">No transient state.</p>{/if}</div><div><h3>Pending timers</h3>{#if selectedBlock.pendingTimers.length}<div class="table-wrap"><table><thead><tr><th>Name</th><th>Due</th><th>Countdown</th><th>Revision</th></tr></thead><tbody>{#each selectedBlock.pendingTimers as timer}<tr><td><code>{timer.name}</code></td><td>{timer.dueAtMs} ms</td><td><span class:stale={state.stale} class="countdown">{state.stale ? 'stale' : formatCountdown(blockCountdown(timer.name))}</span></td><td>{timer.logicRevision}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">No pending timers.</p>{/if}</div></div>
        <div class="detail-columns"><div><h3>Schedules</h3>{#if selectedBlock.schedules.length}<div class="table-wrap"><table class="schedule-table"><thead><tr><th>Name</th><th>Status</th><th>Rule</th><th>Next occurrence (local)</th><th>Countdown</th><th>Offset</th><th>Last outcome</th></tr></thead><tbody>{#each selectedBlock.schedules as schedule}<tr class:selected={schedule.name === selectedScheduleName} tabindex="0" role="button" aria-label={`Schedule ${schedule.name} detail`} on:click={() => selectSchedule(schedule.name)} on:keydown={(event) => { if (event.key === 'Enter' || event.key === ' ') selectSchedule(schedule.name); }}><td><code>{schedule.name}</code>{#if !schedule.enabled}<span class="status-pill muted">disabled</span>{/if}</td><td><span class="status-pill {scheduleStatusPill(schedule.status)}">{schedule.status}</span></td><td>{schedule.ruleSummary}</td><td>{schedule.nextOccurrenceLocal ?? '—'}</td><td><span class:stale={state.stale} class="countdown">{state.stale ? 'stale' : scheduleCountdown(schedule.name)}</span></td><td>{formatUtcOffset(schedule.utcOffsetSeconds)}</td><td>{scheduleOutcome(schedule)}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">No schedules configured.</p>{/if}</div><div><h3>Schedule detail</h3>{#if selectedSchedule}{#if scheduleReason(selectedSchedule)}<div class="logic-error" role="alert">{scheduleReason(selectedSchedule)}</div>{/if}<dl class="facts"><dt>Name</dt><dd><code>{selectedSchedule.name}</code></dd><dt>Kind</dt><dd>{selectedSchedule.kind}</dd><dt>Enabled</dt><dd>{String(selectedSchedule.enabled)}</dd><dt>Rule</dt><dd>{selectedSchedule.ruleSummary}</dd><dt>Next (local)</dt><dd>{selectedSchedule.nextOccurrenceLocal ?? '—'}</dd><dt>Next (UTC)</dt><dd>{selectedSchedule.nextOccurrenceUtcMs === null ? '—' : formatUtcDateTime(selectedSchedule.nextOccurrenceUtcMs)}</dd></dl>{#if scheduleDetailLoading}<p class="subtle">Loading occurrence previews…</p>{/if}{#if scheduleDetailError}<div class="alert" role="alert">{scheduleDetailError}</div>{/if}{#if scheduleDetailPreviews.length}<h4>Next occurrences</h4><div class="table-wrap"><table><thead><tr><th>#</th><th>Local</th><th>UTC</th><th>Weekday</th><th>Offset</th></tr></thead><tbody>{#each scheduleDetailPreviews.slice(0, 3) as occurrence, index}<tr><td>{index + 1}</td><td>{occurrence.local ?? '—'}</td><td>{formatUtcDateTime(occurrence.utcMs)}</td><td>{occurrence.weekday ?? '—'}</td><td>{formatUtcOffset(occurrence.utcOffsetSeconds)}</td></tr>{/each}</tbody></table></div>{#each occurrenceNotes(scheduleDetailPreviews) as note}<p class="subtle">{note}</p>{/each}{:else if !scheduleDetailLoading && !scheduleDetailError}<p class="empty">No future occurrences available.</p>{/if}{:else}<p class="empty">Select a schedule to inspect its occurrences.</p>{/if}</div></div>
        <div class="editor-actions"><button type="button" class="save-button" disabled={validateAutomation(draft).length > 0 || automationSaving} on:click={saveDraft}>{automationSaving ? 'Saving…' : 'Save whole document'}</button><span class="subtle">{validateAutomation(draft).length ? 'Draft has validation errors.' : pendingRestart ? 'Structural changes will show restart required.' : 'Source and enabled changes activate per block.'}</span></div>
        {#if serverErrors.length}<div class="validation-summary" role="alert"><ul>{#each serverErrors as error}<li>{error.path}: {error.message}</li>{/each}</ul></div>{/if}
      </section>

      <section class="panel" aria-label="Execution history"><div class="section-heading"><div><h2>History — {selectedBlock.id}</h2><p class="subtle">Only this block’s executions are shown.</p></div><span>{selectedBlock.executions.length}</span></div>{#if selectedBlock.executions.length}<div class="table-wrap"><table class="execution-history"><thead><tr><th>ID</th><th>Trigger</th><th>Time</th><th>Duration</th><th>Status</th><th>Outputs</th></tr></thead><tbody>{#each selectedBlock.executions as execution}<tr class:selected={execution.executionId === state.selectedExecutionId} class:pinned={execution.executionId === state.selectedExecutionId && state.selectionPinned} tabindex="0" role="button" on:click={() => selectExecution(execution.executionId)} on:keydown={(event) => { if (event.key === 'Enter' || event.key === ' ') selectExecution(execution.executionId); }}><td>{execution.executionId}</td><td><span class="trigger-kind">{triggerLabel(execution.trigger)}</span></td><td>{execution.timeMs} ms</td><td>{formatDuration(execution.durationUs)}</td><td><span class="status-pill logic-{execution.status}">{execution.status}</span></td><td>{execution.effects.length}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">No executions yet. Disabled observations do not create history.</p>{/if}
        {#if selectedExecution}<article class="execution-detail"><div class="section-heading"><div><h3>Execution {selectedExecution.executionId}</h3><span class="subtle">{state.selectionPinned ? 'pinned selection' : 'following newest'}</span></div><button type="button" class="small-button" on:click={() => useForSimulation(selectedExecution)}>Use for simulation</button></div><dl class="facts"><dt>Status</dt><dd>{selectedExecution.status}</dd><dt>Trigger</dt><dd>{triggerSummary(selectedExecution.trigger)}</dd><dt>Logic revision</dt><dd>{selectedExecution.logicRevision ?? '—'}</dd><dt>Duration</dt><dd>{formatDuration(selectedExecution.durationUs)}</dd></dl>{#if selectedExecution.trigger.type === 'schedule'}<h3>Schedule execution</h3><dl class="facts"><dt>Intended occurrence (UTC)</dt><dd>{formatUtcDateTime(selectedExecution.trigger.scheduledForUtcMs)}</dd><dt>Detected (UTC)</dt><dd>{formatUtcDateTime(selectedExecution.trigger.detectedAtUtcMs)}</dd><dt>Handling started (UTC)</dt><dd>{formatUtcDateTime(selectedExecution.trigger.handledAtUtcMs)}</dd><dt>Lateness</dt><dd>{formatAge(selectedExecution.trigger.lateByMs)}</dd><dt>Queue delay</dt><dd>{formatAge(selectedExecution.trigger.queueDelayMs)}</dd><dt>Coalesced occurrences</dt><dd>{selectedExecution.trigger.coalescedCount}</dd><dt>Structural revision</dt><dd>{selectedExecution.trigger.structuralRevision}</dd></dl>{/if}{#if selectedExecution.error}<div class="logic-error" role="alert"><strong>{selectedExecution.error.category}</strong>{#if selectedExecution.error.line !== null} line {selectedExecution.error.line}:{/if} {selectedExecution.error.message}</div>{/if}<h3>Input snapshot</h3><div class="table-wrap"><table><thead><tr><th>Input</th><th>DPT</th><th>Value</th><th>Age</th></tr></thead><tbody>{#each selectedExecution.inputs as input}<tr><td>{input.endpoint}</td><td>{input.dpt}</td><td>{formatValue(input.value)}</td><td>{formatAge(input.ageMs)}</td></tr>{/each}</tbody></table></div><h3>Outputs and timers</h3>{#if selectedExecution.effects.length}<ul>{#each selectedExecution.effects as effect}<li><code>{effect.endpoint}</code> = {formatValue(effect.value)} to <code>{effect.destination}</code></li>{/each}</ul>{:else}<p class="empty">No outputs.</p>{/if}{#if selectedExecution.timerEffects.length}<ul>{#each selectedExecution.timerEffects as effect}<li><code>{effect.name}</code>: {effect.action}</li>{/each}</ul>{/if}{#if selectedExecution.timeContext}<h3>Captured time context (ctx)</h3><dl class="facts"><dt>ctx.now</dt><dd>{formatDateTimeValue(selectedExecution.timeContext.now)}</dd><dt>ctx.sun.dawn</dt><dd>{formatDateTimeValue(selectedExecution.timeContext.sun.dawn)}</dd><dt>ctx.sun.sunrise</dt><dd>{formatDateTimeValue(selectedExecution.timeContext.sun.sunrise)}</dd><dt>ctx.sun.sunset</dt><dd>{formatDateTimeValue(selectedExecution.timeContext.sun.sunset)}</dd><dt>ctx.sun.dusk</dt><dd>{formatDateTimeValue(selectedExecution.timeContext.sun.dusk)}</dd><dt>ctx.sun.elevation</dt><dd>{selectedExecution.timeContext.sun.elevationDegrees === null ? '—' : `${selectedExecution.timeContext.sun.elevationDegrees.toFixed(1)}°`}</dd><dt>ctx.sun.azimuth</dt><dd>{selectedExecution.timeContext.sun.azimuthDegrees === null ? '—' : `${selectedExecution.timeContext.sun.azimuthDegrees.toFixed(1)}°`}</dd></dl>{/if}</article>{/if}
      </section>

      <section class="panel simulation-panel" aria-label="Block simulation"><div class="section-heading"><div><h2>Simulation — {selectedBlock.id}</h2><p class="subtle">Uses this block’s active source, inputs, state, schedules, and timers only. No live state or KNX writes are changed.</p></div><span class="revision-badge">Revision {simulationRevision ?? '—'}</span></div>{#if !simulationDraft}<p class="empty">Loading simulation inputs…</p>{:else}<div class="simulation-kind" role="group" aria-label="Simulation trigger type"><span>Trigger type</span><label><input type="radio" name="simulation-trigger-type" checked={simulationDraft.triggerType === 'input'} on:change={() => simulationTriggerType('input')} /> input</label><label><input type="radio" name="simulation-trigger-type" checked={simulationDraft.triggerType === 'timer'} on:change={() => simulationTriggerType('timer')} /> timer</label><label><input type="radio" name="simulation-trigger-type" checked={simulationDraft.triggerType === 'schedule'} on:change={() => simulationTriggerType('schedule')} /> schedule</label></div>{#if simulationDraft.triggerType === 'timer'}<div class="simulation-trigger-fields"><label>Timer<select aria-label="Simulation timer" value={simulationDraft.triggerTimerName} on:change={(event) => simulationTimer(selectValue(event))}><option value="">Choose timer</option>{#each simulationDraft.pendingTimers as timer}<option value={timer.name}>{timer.name} (due {timer.dueAtMs} ms)</option>{/each}</select></label><label>Fired time<input aria-label="Simulation fired time" type="number" min="0" step="1" value={simulationDraft.timerFiredAtMs ?? ''} on:input={(event) => simulationFiredAt(inputValue(event))} /></label></div>{:else if simulationDraft.triggerType === 'schedule'}<div class="simulation-trigger-fields"><label>Schedule<select aria-label="Simulation schedule" value={simulationDraft.triggerScheduleName} on:change={(event) => simulationSchedule(selectValue(event))}><option value="">Choose schedule</option>{#each selectedBlock.schedules as schedule}<option value={schedule.name}>{schedule.name} — {schedule.ruleSummary}</option>{/each}</select></label><label>Occurrence<select aria-label="Simulation occurrence" value={simulationDraft.scheduleOccurrenceAtMs === null ? '' : String(simulationDraft.scheduleOccurrenceAtMs)} on:change={(event) => simulationOccurrence(Number(selectValue(event)))}>{#if !simulationDraft.schedulePreviews.length}<option value={simulationDraft.scheduleOccurrenceAtMs === null ? '' : String(simulationDraft.scheduleOccurrenceAtMs)}>{simulationDraft.scheduleOccurrenceAtMs === null ? 'Choose occurrence' : 'Next occurrence (not yet previewed)'}</option>{:else}{#each simulationDraft.schedulePreviews as occurrence, index}<option value={occurrence.utcMs}>{occurrence.local ?? formatUtcDateTime(occurrence.utcMs)}{index === 0 ? ' — next' : ''}</option>{/each}{/if}</select></label>{#if simulationPreviewLoading}<span class="subtle">Loading previews…</span>{/if}{#if simulationPreviewError}<span class="alert" role="alert">{simulationPreviewError}</span>{/if}<p class="subtle">The server verifies the selected instant is still a valid previewed occurrence when simulating.</p></div>{:else}<div class="simulation-trigger-fields"><label>Input<select aria-label="Simulation triggering input" value={simulationDraft.triggerEndpoint} on:change={(event) => simulationTriggerEndpoint(selectValue(event))}><option value="">Choose input</option>{#each simulationDraft.inputs as input}<option value={input.endpoint}>{input.endpoint} ({input.dpt})</option>{/each}</select></label><label>Current value{#if simulationTriggerInput?.dpt === '1.001'}<select aria-label="Simulation current trigger value" value={simulationDraft.triggerValue === null ? '' : String(simulationDraft.triggerValue)} on:change={(event) => updateSimulationDraft({ ...simulationDraft!, triggerValue: simulationBoolean(event) })}><option value="">Choose value</option><option value="false">false</option><option value="true">true</option></select>{:else}<input aria-label="Simulation current trigger value" type="number" min="0" max="100" step="1" value={simulationDraft.triggerValue ?? ''} on:input={(event) => updateSimulationDraft({ ...simulationDraft!, triggerValue: simulationNumber(event) })} />{/if}</label><label>Previous value{#if simulationTriggerInput?.dpt === '1.001'}<select aria-label="Simulation previous trigger value" value={simulationDraft.previousValue === null ? '' : String(simulationDraft.previousValue)} on:change={(event) => updateSimulationDraft({ ...simulationDraft!, previousValue: simulationBoolean(event) })}><option value="">unknown</option><option value="false">false</option><option value="true">true</option></select>{:else}<input aria-label="Simulation previous trigger value" type="number" min="0" max="100" step="1" value={simulationDraft.previousValue ?? ''} on:input={(event) => updateSimulationDraft({ ...simulationDraft!, previousValue: simulationNumber(event) })} />{/if}</label></div>{/if}<h3>Input snapshot</h3><div class="table-wrap"><table class="simulation-table"><thead><tr><th>Input</th><th>DPT</th><th>Value</th><th>Valid</th><th>Age</th></tr></thead><tbody>{#each simulationDraft.inputs as input, index}{@const isTrigger = simulationDraft.triggerType === 'input' && input.endpoint === simulationDraft.triggerEndpoint}<tr class:simulation-trigger-row={isTrigger}><td><code>{input.endpoint}</code></td><td>{input.dpt}</td><td>{#if input.dpt === '1.001'}<select aria-label={`Simulation ${input.endpoint} value`} disabled={!input.valid || isTrigger} value={input.value === null ? '' : String(input.value)} on:change={(event) => updateSimulationDraft({ ...simulationDraft!, inputs: simulationDraftRequired().inputs.map((item, current) => current === index ? { ...item, value: simulationBoolean(event) } : item) })}><option value="">Choose value</option><option value="false">false</option><option value="true">true</option></select>{:else}<input aria-label={`Simulation ${input.endpoint} value`} disabled={!input.valid || isTrigger} type="number" min="0" max="100" value={input.value ?? ''} on:input={(event) => updateSimulationDraft({ ...simulationDraft!, inputs: simulationDraftRequired().inputs.map((item, current) => current === index ? { ...item, value: simulationNumber(event) } : item) })} />{/if}</td><td><input aria-label={`Simulation ${input.endpoint} validity`} type="checkbox" checked={input.valid} disabled={isTrigger} on:change={(event) => updateSimulationDraft({ ...simulationDraft!, inputs: simulationDraftRequired().inputs.map((item, current) => current === index ? { ...item, valid: (event.currentTarget as HTMLInputElement).checked } : item) })} /></td><td><input aria-label={`Simulation ${input.endpoint} age`} disabled={!input.valid || isTrigger} type="number" min="0" value={input.ageMs ?? ''} on:input={(event) => updateSimulationDraft({ ...simulationDraft!, inputs: simulationDraftRequired().inputs.map((item, current) => current === index ? { ...item, ageMs: simulationAge(event) } : item) })} /></td></tr>{/each}</tbody></table></div>{#if simulationErrors.length}<div class="validation-summary" role="alert"><ul>{#each simulationErrors as error}<li>{error}</li>{/each}</ul></div>{/if}{#if simulationError}<div class="logic-error simulation-error" role="alert">{simulationError}{#if simulationFieldErrors.length}<ul>{#each simulationFieldErrors as error}<li>{error}</li>{/each}</ul>{/if}</div>{/if}<div class="editor-actions"><button type="button" class="save-button" disabled={!canSimulate} on:click={runSimulation}>{simulationRunning ? 'Running…' : 'Run simulation'}</button><span class="subtle">Simulation is effect-free and block-scoped.</span></div>{#if simulationResult}<article class:simulation-failed={simulationResult.status === 'failed'} class="simulation-result" aria-label="Simulation result"><h3>Simulation {simulationResult.status}</h3>{#if simulationResult.error}<div class="logic-error"><strong>{simulationResult.error.category}</strong> {simulationResult.error.message}</div>{:else}<p>{triggerSummary(simulationResult.trigger)}</p>{#if simulationResult.effects.length}<h3>Proposed outputs</h3><ul>{#each simulationResult.effects as effect}<li><code>{effect.endpoint}</code> = {formatValue(effect.value)} to <code>{effect.destination}</code></li>{/each}</ul>{/if}{#if simulationResult.timerEffects.length}<h3>Proposed timers</h3><ul>{#each simulationResult.timerEffects as effect}<li><code>{effect.name}</code>: {effect.action}</li>{/each}</ul>{/if}{/if}<p class="subtle">No KNX write sent.</p></article>{/if}{/if}</section>
    {/if}

    <section class="grid two-columns" aria-label="Global diagnostics"><article class="panel"><h2>Site time</h2>{#if snapshot.siteTime}<dl class="facts"><dt>Zone</dt><dd><code>{snapshot.siteTime.timezone}</code></dd><dt>Local time at sample</dt><dd>{snapshot.siteTime.localTime ?? '—'} {#if !snapshot.siteTime.clockOk}<span class="status-pill bad">clock error</span>{/if}</dd><dt>UTC offset</dt><dd>{formatUtcOffset(snapshot.siteTime.utcOffsetSeconds)}</dd><dt>Coordinates</dt><dd>{snapshot.siteTime.coordinates ? `${snapshot.siteTime.coordinates.latitude.toFixed(4)}, ${snapshot.siteTime.coordinates.longitude.toFixed(4)}` : 'Astronomy unavailable'}</dd><dt>Astronomy</dt><dd>{snapshot.siteTime.astronomy}{snapshot.siteTime.astronomyReason ? ` — ${snapshot.siteTime.astronomyReason}` : ''}</dd><dt>Dawn</dt><dd>{snapshot.siteTime.sun.dawn ?? '—'}</dd><dt>Sunrise</dt><dd>{snapshot.siteTime.sun.sunrise ?? '—'}</dd><dt>Sunset</dt><dd>{snapshot.siteTime.sun.sunset ?? '—'}</dd><dt>Dusk</dt><dd>{snapshot.siteTime.sun.dusk ?? '—'}</dd><dt>Clock</dt><dd>{snapshot.siteTime.clockOk ? 'healthy' : 'error'}</dd><dt>Scheduler</dt><dd>{snapshot.siteTime.schedulerOk ? 'healthy' : 'error'}</dd></dl>{:else}<p class="empty">No site time information in this snapshot.</p>{/if}</article><article class="panel"><h2>Global connection and writes</h2><dl class="facts"><dt>Connection</dt><dd>{snapshot.connection.state}</dd><dt>Observed input</dt><dd>{formatValue(snapshot.values.input.observed)}</dd><dt>Observed output</dt><dd>{formatValue(snapshot.values.output.observed)}</dd><dt>Requested output</dt><dd>{formatValue(snapshot.values.output.requested)}</dd><dt>Write status</dt><dd>{snapshot.write.status}{snapshot.write.error ? ` — ${snapshot.write.error}` : ''}</dd></dl></article><article class="panel"><h2>Dashboard status</h2><dl class="facts"><dt>Snapshot event</dt><dd>{snapshot.revision}</dd><dt>Selected block</dt><dd>{selectedBlock?.id ?? '—'}</dd><dt>Block revision</dt><dd>{selectedBlock?.activeLogicRevision ?? '—'}</dd><dt>Restart required</dt><dd>{String(snapshot.restartRequired)}</dd></dl></article></section>
    <section class="panel" aria-label="Recent KNX telegrams"><div class="section-heading"><h2>Recent telegrams</h2><span>{snapshot.telegrams.length}</span></div>{#if snapshot.telegrams.length}<div class="table-wrap"><table><thead><tr><th>Time</th><th>Source</th><th>Destination</th><th>Service</th><th>DPT</th><th>Value</th></tr></thead><tbody>{#each snapshot.telegrams as telegram}<tr><td>{displayTime(telegram.time)}</td><td>{telegram.source ?? '—'}</td><td><code>{telegram.destination}</code></td><td>{telegram.service}</td><td>{telegram.dpt}</td><td>{formatValue(telegram.value)}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">No telegrams observed yet.</p>{/if}</section>
    <section class="panel" aria-label="Recent runtime logs"><div class="section-heading"><h2>Recent logs</h2><span>{snapshot.logs.length}</span></div>{#if snapshot.logs.length}<div class="table-wrap"><table><thead><tr><th>Time</th><th>Level</th><th>Target</th><th>Message</th><th>Fields</th></tr></thead><tbody>{#each snapshot.logs as log}<tr><td>{displayTime(log.time)}</td><td><span class="level level-{log.level.toLowerCase()}">{log.level}</span></td><td>{log.target}</td><td>{log.message}</td><td class="fields">{displayFields(log.fields) || '—'}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">No runtime logs captured yet.</p>{/if}</section>
  {:else}<section class="panel loading" aria-live="polite">Loading runtime snapshot…</section>{/if}
  <footer>Snapshot revision {state.revision}</footer>
</main>
